#include <stdio.h>

#define CAN_FISH (1 << 0)
#define CAN_SUN  (1 << 1)
#define CAN_NAP  (1 << 2)

int main(void) {
    int cat = {start};

    printf("能领小鱼干吗？%s\n", (cat & CAN_FISH) ? "能" : "不能");
    printf("能晒太阳吗？%s\n", (cat & CAN_SUN) ? "能" : "不能");
    printf("能睡猫窝吗？%s\n", (cat & CAN_NAP) ? "能" : "不能");

    cat = cat | CAN_SUN;
    printf("拨开晒太阳之后：%s\n", (cat & CAN_SUN) ? "能" : "不能");

    cat = cat & ~CAN_NAP;
    printf("按灭睡猫窝之后：%s\n", (cat & CAN_NAP) ? "能" : "不能");

    cat = cat ^ CAN_FISH;
    printf("再拨一下小鱼干那盏：%s\n", (cat & CAN_FISH) ? "能" : "不能");
    return 0;
}
